+            if has_witness:
+                prevtx["witnessScript"] = witness_script
+            prevtxs[addr_type] = prevtx
+
+        self.generate(node, 1)
+
+        # Spend from each multisig address
+        outval = value - Decimal("0.00002000")
+        out_addr = getnewdestination('bech32')[2]
